import sys

def precompute_dp(max_n):
    dp = [[0]*(max_n+1) for _ in range(max_n+1)]
    dp[0][0] = 1
    for i in range(1, max_n+1):
        for j in range(1, i+1):
            val = dp[i-1][j-1] + dp[i-1][j]
            dp[i][j] = val if val <= 10**18 else 10**18
    return dp

def kth_combination(n, k, dp):
    res = []
    last = 0
    for i in range(n, 0, -1):
        for x in range(last+1, n+1):
            cnt = dp[n - x][i - 1] if n - x >= 0 and i - 1 >= 0 else 0
            if cnt >= k:
                res.append(x)
                last = x
                break
            else:
                k -= cnt
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    dp = precompute_dp(n)
    cycles = kth_combination(n, k, dp)

    perm = list(range(1, n+1))
    for c in cycles:
        perm[c-1] = c
    print(' '.join(map(str, perm)))

if __name__ == "__main__":
    main()

import sys

def precompute_dp(max_n):
    dp = [0] * (max_n + 1)
    dp[0] = 1
    for n in range(1, max_n + 1):
        s = 0
        for L in range(1, n + 1):
            s += dp[n - L]
        dp[n] = s
    return dp

def kth_sequence(n, k, dp):
    res = []
    remaining = n
    while remaining > 0:
        for L in range(1, remaining + 1):
            cnt = dp[remaining - L]
            if k > cnt:
                k -= cnt
            else:
                res.append(L)
                remaining -= L
                break
    return res

def build_permutation(n, seq):
    perm = [0] * n
    cur = 1
    for L in seq:
        for i in range(L):
            perm[cur - 1 + i] = cur + (i + 1) % L
        cur += L
    return perm

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    dp = precompute_dp(n)
    seq = kth_sequence(n, k, dp)
    perm = build_permutation(n, seq)
    print(' '.join(map(str, perm)))

if __name__ == "__main__":
    main()
